import { mkdir, rename, rm, stat } from 'node:fs/promises';
import path from 'node:path';

/**
 * Stores media files under a root directory on the local disk.
 *
 * Every storage driver exposes the same methods, so a cloud driver (e.g. S3)
 * can replace this one without changing upload or processing code.
 * Keys are relative, slash-separated paths such as "videos/<id>/720p.mp4".
 */
export function createLocalStorage({ rootDir }) {
  const root = path.resolve(rootDir);

  // Keys are generated by the server, but resolving defensively guarantees a key
  // can never point outside the storage root (e.g. "../../etc/passwd").
  function resolveKey(key) {
    const filePath = path.resolve(root, key);
    if (!filePath.startsWith(root + path.sep)) {
      throw new Error(`Storage key escapes the storage root: ${key}`);
    }
    return filePath;
  }

  return {
    /** Directory for in-progress files; on the same disk as the root so moves are instant. */
    tempDir: path.join(root, 'tmp'),

    /** Moves a local file into storage under `key`. Returns its size in bytes. */
    async put(key, sourcePath) {
      const destination = resolveKey(key);
      await mkdir(path.dirname(destination), { recursive: true });
      await rename(sourcePath, destination);
      return (await stat(destination)).size;
    },

    /**
     * Path of a stored file on the local disk, for tools like FFmpeg.
     * A remote driver would download the file to a temporary path instead.
     */
    async toLocalPath(key) {
      return resolveKey(key);
    },

    /** Deletes a file, or everything under a key prefix such as "videos/<id>". */
    async remove(keyOrPrefix) {
      await rm(resolveKey(keyOrPrefix), { recursive: true, force: true });
    },
  };
}
